import '../../features/response/domain/response_playbooks.dart';

/// Полные русские инструкции реагирования, привязанные к стабильным ID.
class RussianResponseContent {
  RussianResponseContent._();
  static const Map<String, Map<String,Object>> _data = {
    'account-compromise': {'title':'Возможно, аккаунт скомпрометирован','summary':'Вы заметили неизвестные входы, изменённые данные восстановления, отправленные не вами сообщения или неожиданные запросы аутентификации.','firstAction':'Используйте отдельное доверенное устройство и откройте сервис через официальное приложение или известный адрес.','steps':['Сначала защитите основную почту, если она затронута: через неё часто сбрасывают пароли других сервисов.','Замените пароль уникальным и включите доступный надёжный метод MFA.','Проверьте адреса и номера восстановления, ключи доступа и методы аутентификации; удалите незнакомые.','Завершите неизвестные сеансы и отзовите неизвестные подключённые приложения или токены, если сервис это позволяет.','Проверьте правила пересылки, фильтры почты, отправленные сообщения и недавние изменения аккаунта.','Если затронут рабочий или учебный аккаунт, немедленно уведомите ИТ- или службу безопасности организации.'],'preserve':['Зафиксируйте письма оповещений, время входов, сведения об устройствах и сеансах, а также уведомления аккаунта.','Сохраните исходные сообщения и заголовки, если они доступны; запишите, что и когда вы изменили.'],'avoid':['Не сообщайте пароли, OTP, коды восстановления и ссылки сеансов тем, кто предлагает помощь.','Не используйте ссылки восстановления и номера телефонов из неожиданных сообщений.','Не удаляйте важные оповещения, пока не зафиксировали их сведения.'],'limit':'ORVIKA не проверяет доступ к аккаунту, не завершает сеансы и не восстанавливает аккаунты. Следуйте официальной процедуре сервиса; названия и шаги различаются.'},
    'payment-fraud': {'title':'Подозрительный или несанкционированный платёж','summary':'Вы перевели деньги под давлением, подтвердили неожиданный платёж, раскрыли платёжные данные или обнаружили неизвестную операцию.','firstAction':'Немедленно свяжитесь с банком или платёжным провайдером через официальное приложение, номер на карте или независимо проверенный сайт.','steps':['Попросите провайдера защитить затронутый счёт, карту или кошелёк и объяснить порядок оспаривания или отзыва операции.','Сообщите о несанкционированной операции или мошенничестве; укажите номер, сумму, дату и получателя.','С доверенного устройства смените раскрытые банковские и почтовые пароли; проверьте сеансы и платёжные поручения.','Если могли быть скомпрометированы учётные данные или SIM-карта, уведомите банк и мобильного оператора.','Используйте официальный канал обращения в правоохранительные органы вашей юрисдикции и сохраните номер обращения.'],'preserve':['Сохраните идентификаторы операций, банковские уведомления, чеки, данные получателя, журналы звонков и переписку.','Запишите, когда обнаружили проблему и когда связались с провайдером.'],'avoid':['Не платите тем, кто гарантирует возврат денег или требует предоплату.','Не подтверждайте новые запросы на списание, платёжные поручения или сеансы удалённого доступа.','Не используйте контакты, предоставленные предполагаемым мошенником.'],'limit':'Платёж может быть необратимым. ORVIKA не блокирует счета, не отслеживает средства и не подаёт заявления. Свяжитесь с провайдером без промедления.'},
    'lost-device': {'title':'Потерян телефон, компьютер или другое устройство','summary':'Устройство пропало, было украдено или может попасть в руки постороннего.','firstAction':'С другого доверенного устройства воспользуйтесь официальной службой безопасности аккаунта и поиска устройства производителя или платформы.','steps':['Если возможно, отметьте устройство как потерянное или заблокируйте его удалённо; оцените необходимость стирания с учётом данных и шансов возврата.','Свяжитесь с мобильным оператором, чтобы заблокировать SIM/eSIM и защитить номер.','Смените пароли основной почты, финансовых и идентификационных аккаунтов, если устройство могло быть разблокировано или хранило пароли.','Завершите сеансы доверенных устройств и проверьте способы восстановления с другого защищённого устройства.','Сообщите о предполагаемой краже местным органам и выполните внутреннюю процедуру организации для управляемого устройства.'],'preserve':['Сохраните серийный номер, IMEI (если применимо), подтверждение покупки и официальные уведомления безопасности.','Запишите, когда и где устройство видели в последний раз и какие меры блокировки или сообщения были предприняты.'],'avoid':['Не вступайте в конфронтацию и не встречайтесь с человеком, утверждающим, что нашёл устройство; обратитесь к компетентным органам.','Не выполняйте просьбы отключить защиту устройства или раскрыть учётные данные.','Не считайте оценку местоположения точной и безопасной для самостоятельных действий.'],'limit':'Удалённый поиск, блокировка и стирание зависят от предварительных настроек, связи и платформы. Стирание может повлиять на доказательства и восстановление.'},
    'suspected-malware': {'title':'На устройстве может быть вредоносное ПО','summary':'Появились неожиданные окна, предупреждения, неизвестные приложения, необычная активность аккаунтов или странное поведение после открытия файла.','firstAction':'Прекратите вводить пароли и платёжные данные на устройстве. При подозрении на активную компрометацию по возможности отключите его от сетей.','steps':['Для изменения важных паролей используйте отдельное доверенное устройство; о корпоративном устройстве сообщите службе безопасности.','Не открывайте подозрительный файл повторно и не устанавливайте программы по совету всплывающих окон или неизвестных звонящих.','Используйте встроенные или надёжные средства защиты из официальных источников и следуйте их документации.','После оценки ситуации и подтверждения безопасности обновите ОС и приложения.','Если учётные данные могли быть раскрыты, смените их с другого доверенного устройства и завершите активные сеансы.','При серьёзном или рабочем инциденте сохраните состояние устройства и обратитесь к специалистам до очистки или переустановки.'],'preserve':['Зафиксируйте текст предупреждений, имена файлов, источник загрузки, время и результаты средств защиты.','Сохраните письма, URL и снимки экрана; не загружайте конфиденциальные файлы в общедоступные сервисы анализа.'],'avoid':['Не запускайте случайные скрипты очистки, исправления реестра и неизвестные антивирусы.','Не сбрасывайте устройство и не удаляйте файлы до оценки потребностей расследования и восстановления.','Не подключайте без необходимости резервные диски и другие устройства.'],'limit':'Эти признаки не доказывают наличие вредоносного ПО. ORVIKA не сканирует файлы и процессы и не очищает устройства. Серьёзные инциденты требуют квалифицированного анализа.'},
    'identity-exposure': {'title':'Раскрыты личные данные или сведения, удостоверяющие личность','summary':'Документы, личные сведения, учётные данные или закрытые записи могли попасть к ненадёжному лицу или сервису.','firstAction':'Определите, какие именно сведения раскрыты, и защитите зависящие от них аккаунты и сервисы.','steps':['С доверенного устройства смените раскрытые и повторно используемые пароли; включите MFA, если доступна.','Если раскрыты документы, финансовые сведения или официальные учётные данные, свяжитесь с выдавшей организацией по независимо проверенному каналу.','Уточните в финансовых организациях варианты мониторинга, замены, ограничений или других мер защиты.','Проверьте настройки восстановления и следите за уведомлениями о сбросе пароля, кредитах, операциях и проверке личности.','Сообщите об утечке через официальный канал по вопросам конфиденциальности, регулятора или правоохранительных органов вашей юрисдикции.'],'preserve':['Сохраните исходное уведомление, переписку, даты, категории затронутых данных и номера обращений.','Запишите, кого уведомили и какие рекомендации или меры защиты вам предоставили.'],'avoid':['Не публикуйте раскрытый документ или полные персональные идентификаторы, обращаясь за помощью.','Не отправляйте дополнительные документы непроверенному агенту по восстановлению.','Не считайте, что удаление публикации или сообщения удаляет уже скопированные материалы.'],'limit':'Доступные меры защиты личности и порядок сообщения зависят от типа данных и юрисдикции. ORVIKA не может определить, были ли сведения скопированы или использованы.'},
  };
  static ResponsePlaybook localize(ResponsePlaybook item,String code) {
    if(code!='ru') return item; final v=_data[item.id]; if(v==null)return item;
    return ResponsePlaybook(id:item.id,title:v['title']! as String,scenario:item.scenario,summary:v['summary']! as String,firstAction:v['firstAction']! as String,steps:List<String>.unmodifiable(v['steps']! as List<String>),preserve:List<String>.unmodifiable(v['preserve']! as List<String>),avoid:List<String>.unmodifiable(v['avoid']! as List<String>),limit:v['limit']! as String);
  }
}
